describe('Async Login Spinner Visibility', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display spinner while async login request is in progress', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Fill in login form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the login request to be sent
    cy.wait('@loginRequest');

    // Verify spinner is visible
    cy.get('[data-testid="login-spinner"]').should('be.visible');
    cy.get('[data-testid="login-spinner"]').should('contain', 'Logging in...');

    // Verify login button is disabled during request
    cy.get('[data-testid="login-button"]').should('be.disabled');

    // Verify error message is not visible yet
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify spinner is still visible after a short delay
    cy.get('[data-testid="login-spinner"]').should('be.visible');
  });

  it('should hide spinner and show error message when login fails', () => {
    // Intercept login API call and mock a failed response
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequest');

    // Fill in login form with invalid credentials
    cy.get('[data-testid="email-input"]').type('wrong@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');

    // Click login button
    cy.get('[data-testid="login-button"]').click();

    // Wait for the login request
    cy.wait('@loginRequest');

    // Verify spinner was visible during request
    cy.get('[data-testid="login-spinner"]').should('be.visible');

    // Verify spinner is hidden after response
    cy.get('[data-testid="login-spinner"]').should('not.exist');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');

    // Verify login button is re-enabled
    cy.get('[data-testid="login-button"]').should('not.be.disabled');
  });
});
